#!/usr/bin/env Rscript
# Supplementary Figure S8: evidence-layer audit of the PRII candidate network.
# Run from project root: Rscript graph/FigS8_PRII_network_evidence_audit.R
# This is a hypothesis map; it does not establish binding, activation, secretion, or causality.
suppressPackageStartupMessages({library(readr); library(dplyr); library(ggplot2); library(patchwork); library(scales)})
options(stringsAsFactors = FALSE)
root <- normalizePath('.', mustWork=TRUE)
graph_dir <- file.path(root,'graph'); out_dir <- file.path(root,'results/supplementary/S8_network_evidence_audit')
dir.create(out_dir, recursive=TRUE, showWarnings=FALSE)
paths <- c(integrated_nodes='results/network_integrated/integrated_nodes.csv', ppi_nodes='results/network_ppi/ppi_nodes.csv', lr_sample='results/network_ligand_receptor/sample_level_lr_scores.csv', tf_all='results/network_tf/mouse_tf_target_edges.csv',tf_fig6='graph/Fig6_PRII_TF_edges_top8.csv',tf_stats='results/network_tf/mouse_tf_psps_spearman.csv',ppi_all='results/network_ppi/ppi_edges.csv',ppi_fig6='graph/Fig6_PRII_PPI_edges_core_score90.csv',ppi_hubs='results/network_ppi/ppi_top_hubs.csv',lr_prior='results/network_ligand_receptor/ligand_receptor_prior_edges.csv',lr_all='results/network_ligand_receptor/lr_edge_summary.csv',lr_fig6='graph/Fig6_PRII_LR_edges_top15.csv',integrated='results/network_integrated/integrated_edges.csv')
missing <- paths[!file.exists(file.path(root,paths))]; if(length(missing)) stop('Missing S8 input(s): ',paste(missing,collapse=', '))
lab_expr <- '表达关联'; lab_prior <- '数据库先验'; lab_lr <- '候选配体–受体表达支持'
read <- function(key) read_csv(file.path(root,paths[[key]]),show_col_types=FALSE)
add_scope <- function(x,evidence,components,source,kind,scope) x %>% mutate(evidence_type=evidence,evidence_components=components,prior_source=source,edge_type=kind,evidence_scope=scope)
tf_all <- add_scope(read('tf_all'),lab_expr,'表达关联;数据库先验','DoRothEA','TF–target','complete_source_edges') %>% mutate(edge_id=sprintf('tf_source_%04d',row_number()))
tf_fig6 <- add_scope(read('tf_fig6'),lab_expr,'表达关联;数据库先验','DoRothEA','TF–target','Figure6_selected_subset') %>% select(-any_of('evidence_label')) %>% mutate(edge_id=sprintf('tf_Figure6_%03d',row_number()))
ppi_all <- add_scope(read('ppi_all'),lab_prior,lab_prior,'STRING','STRING PPI','complete_source_edges') %>% mutate(directed_interpretation='undirected',edge_id=sprintf('ppi_source_%04d',row_number()))
ppi_fig6 <- add_scope(read('ppi_fig6'),lab_prior,lab_prior,'STRING','STRING PPI','Figure6_PRII_core_combined_score_ge_0.90') %>% select(-any_of('evidence_label')) %>% mutate(directed_interpretation='undirected',edge_id=sprintf('ppi_Figure6_core_%03d',row_number()))
lr_prior <- add_scope(read('lr_prior'),lab_prior,lab_prior,'OmniPath','ligand–receptor prior','OmniPath_prior_only') %>% mutate(edge_id=sprintf('OmniPath_prior_%03d',row_number()))
lr_all <- add_scope(read('lr_all'),lab_lr,lab_lr,'OmniPath + sample expression','candidate ligand–receptor','complete_candidate_LR_summary') %>% mutate(evidence_type=if_else(n_supported_samples > 0, lab_lr, lab_prior), evidence_components=if_else(n_supported_samples > 0, '数据库先验;样本表达支持', '数据库先验;该汇总行无样本表达支持'), prior_source=if_else(n_supported_samples > 0, 'OmniPath + sample expression', 'OmniPath'), statistical_unit='sample', edge_id=sprintf('lr_summary_%03d',row_number()))
lr_fig6 <- add_scope(read('lr_fig6'),lab_lr,lab_lr,'OmniPath + sample expression','candidate ligand–receptor','Figure6_receiver_specific_subset') %>% select(-any_of('evidence_label')) %>% mutate(statistical_unit='sample',edge_id=sprintf('lr_Figure6_receiver_%02d',row_number()),edge_label=paste0(ligand,'→',receptor))
integrated <- read('integrated') %>% mutate(evidence_type=case_when(edge_type=='TF-target (DoRothEA + expression)'~lab_expr,edge_type=='STRING PPI'~lab_prior,edge_type=='scRNA LR expression support'~lab_lr,TRUE~as.character(evidence_type)),evidence_components=case_when(edge_type=='TF-target (DoRothEA + expression)'~'表达关联;数据库先验',edge_type=='STRING PPI'~lab_prior,edge_type=='scRNA LR expression support'~lab_lr,TRUE~as.character(evidence_components)),prior_source=case_when(edge_type=='TF-target (DoRothEA + expression)'~'DoRothEA',edge_type=='STRING PPI'~'STRING',edge_type=='scRNA LR expression support'~'OmniPath + sample expression',TRUE~as.character(prior_source)),evidence_scope='integrated_network_selected_subset',edge_id=sprintf('integrated_%03d',row_number()))
integrated_nodes <- read('integrated_nodes') %>% mutate(evidence_context='integrated_network_selected_subset')
ppi_nodes <- read('ppi_nodes') %>% mutate(evidence_type=lab_prior,evidence_components=lab_prior,prior_source='STRING',network_interpretation='undirected database-prior node degree')
lr_sample <- read('lr_sample') %>% mutate(evidence_type=if_else(supported,lab_lr,lab_prior),evidence_components=if_else(supported,'数据库先验;样本表达支持','数据库先验;该样本未达到表达支持阈值'),prior_source=if_else(supported,'OmniPath + sample expression','OmniPath'),statistical_unit='sample')
write_csv(integrated_nodes,file.path(out_dir,'integrated_nodes_normalized.csv')); write_csv(ppi_nodes,file.path(out_dir,'string_nodes_normalized.csv')); write_csv(lr_sample,file.path(out_dir,'lr_sample_level_scores_normalized.csv'))
write_csv(integrated,file.path(out_dir,'integrated_edges_normalized.csv')); write_csv(tf_all,file.path(out_dir,'tf_target_edges_complete_normalized.csv')); write_csv(tf_fig6,file.path(out_dir,'tf_target_edges_Figure6_subset_normalized.csv')); write_csv(ppi_all,file.path(out_dir,'string_ppi_edges_complete_normalized.csv')); write_csv(ppi_fig6,file.path(out_dir,'string_ppi_edges_Figure6_core_score90_normalized.csv')); write_csv(lr_prior,file.path(out_dir,'omnipath_prior_edges_normalized.csv')); write_csv(lr_all,file.path(out_dir,'lr_edges_complete_summary_normalized.csv')); unlink(file.path(out_dir,'lr_edges_complete_sample_supported_normalized.csv')); write_csv(lr_fig6,file.path(out_dir,'lr_edges_Figure6_receiver_specific_normalized.csv'))
tf_stats <- read('tf_stats') %>% mutate(evidence_type=lab_expr,evidence_components='表达关联;数据库先验',prior_source='DoRothEA')
ppi_hubs <- read('ppi_hubs') %>% mutate(evidence_type=lab_prior,evidence_components=lab_prior,prior_source='STRING',network_interpretation='undirected database-prior degree')
write_csv(tf_stats,file.path(out_dir,'tf_prii_spearman_normalized.csv')); write_csv(ppi_hubs,file.path(out_dir,'string_hubs_normalized.csv'))
layer_order <- c(lab_expr,lab_prior,lab_lr)
lr_unique <- n_distinct(lr_all$ligand,lr_all$receptor); lr_fig6_unique <- n_distinct(lr_fig6$ligand,lr_fig6$receptor)
stopifnot(nrow(integrated_nodes)==189L, nrow(ppi_nodes)==179L, nrow(lr_sample)==4059L)
stopifnot(nrow(integrated)==253L, nrow(tf_fig6)==96L, nrow(ppi_fig6)==37L, nrow(lr_fig6)==15L, nrow(tf_all)==949L, nrow(ppi_all)==743L, nrow(lr_prior)==99L, nrow(lr_all)==297L, lr_fig6_unique==8L)
stopifnot(all(integrated$evidence_type %in% layer_order), all(tf_all$evidence_type==lab_expr), all(ppi_all$evidence_type==lab_prior), all(lr_prior$evidence_type==lab_prior), all(lr_all$evidence_type %in% c(lab_lr,lab_prior)), all(lr_sample$evidence_type %in% c(lab_prior,lab_lr)))
layer_counts <- tibble(evidence_type=layer_order,n_edges=c(sum(integrated$evidence_type==lab_expr),sum(integrated$evidence_type==lab_prior),sum(integrated$evidence_type==lab_lr)),edge_type=c('TF–target','STRING PPI','Candidate ligand–receptor'),source=c('DoRothEA + observed expression association','STRING combined score ≥ 0.70','OmniPath prior + sample expression support'),interpretation=c('expression/activity association with prior components','undirected database prior','candidate sample-level expression support'))
write_csv(layer_counts,file.path(out_dir,'evidence_layer_counts.csv'))
denominators <- tibble(item=c('integrated_nodes','integrated_edges','integrated_TF_edges','integrated_STRING_edges','integrated_candidate_LR_edges','complete_TF_source_rows','complete_STRING_source_rows','complete_OmniPath_prior_rows','complete_LR_summary_rows','unique_LR_pairs_in_sample_supported_summary','Figure6_TF_rows','Figure6_STRING_PRII_core_score_ge_0.90_rows','Figure6_LR_receiver_specific_rows','unique_LR_pairs_in_Figure6_subset','TF_mouse_bulk_n','TF_TCGA_purity_complete_n','LR_sample_cohort_n','STRING_required_combined_score'),value=c('189',nrow(integrated),sum(integrated$evidence_type==lab_expr),sum(integrated$evidence_type==lab_prior),sum(integrated$evidence_type==lab_lr),nrow(tf_all),nrow(ppi_all),nrow(lr_prior),nrow(lr_all),lr_unique,nrow(tf_fig6),nrow(ppi_fig6),nrow(lr_fig6),lr_fig6_unique,21,149,16,'0.70'),evidence_type=c(NA,NA,lab_expr,lab_prior,lab_lr,lab_expr,lab_prior,lab_prior,lab_lr,lab_lr,lab_expr,lab_prior,lab_lr,lab_lr,lab_expr,lab_expr,lab_lr,lab_prior),note=c('nodes in integrated network','selected integrated edges; not all source rows','top eight edges for each of 12 prespecified TFs','integrated STRING selection; complete source contains 743 edges','integrated selection; not the 15 Figure 6 LR rows','full source table','full STRING source table','OmniPath prior-only set restricted to focused ligand/receptor lists','sample-by-receiver summary rows; 115 rows have support and 182 are prior-only','deduplicated molecular pairs','Figure 6 display subset','Figure 6 display subset','receiver-specific rows','deduplicated within the selected rows','GSE292815 bulk','TCGA purity-complete sensitivity cohort','sample is the support unit; eligible n varies by edge','STRING required_score=700'))
write_csv(denominators,file.path(out_dir,'S8_denominator_and_threshold_audit.csv'))
ink <- '#243746'; muted <- '#6D7E87'; blue <- '#327C9A'; grey <- '#8D969B'; green <- '#2E8B72'; coral <- '#D16B58'; fill_values <- setNames(c(blue,grey,green),layer_order)
bar_dat <- layer_counts %>% mutate(x=row_number())
p_a <- ggplot(bar_dat,aes(x,n_edges,fill=evidence_type))+geom_col(width=.62,colour='white',linewidth=.4)+geom_text(aes(label=n_edges),vjust=-.35,fontface='bold',colour=ink,size=3.4)+scale_fill_manual(values=fill_values)+scale_x_continuous(breaks=1:3,labels=c('TF–target','STRING\nPPI','Candidate\nLR'))+scale_y_continuous(limits=c(0,175),breaks=c(0,50,100,150),expand=c(0,0))+labs(title='A  Integrated network evidence layers',subtitle='189 nodes; 253 selected edges',x=NULL,y='Number of edges')+theme_classic(base_size=9)+theme(legend.position='none',plot.title=element_text(face='bold',colour=ink,size=10),plot.subtitle=element_text(colour=muted,size=7.5),axis.text=element_text(colour=muted),axis.title.y=element_text(colour=muted,size=8),axis.line=element_line(colour='#AAB5BA',linewidth=.35))
tf_plot <- tf_stats %>% mutate(label=ifelse(!is.na(tf_label),tf_label,toupper(tf)),q=fdr_BH) %>% arrange(spearman_rho) %>% mutate(label=factor(label,levels=label),sig=q<.05)
p_b <- ggplot(tf_plot,aes(spearman_rho,label,colour=sig))+geom_vline(xintercept=0,linetype='dashed',colour='#B5BFC3',linewidth=.35)+geom_segment(aes(x=0,xend=spearman_rho,yend=label),linewidth=.7,colour='#A4B2B7')+geom_point(size=2.5)+geom_text(aes(label=sprintf('q=%.3f',q),hjust=ifelse(spearman_rho>=0,-.12,1.12)),size=2.4,colour=muted)+scale_colour_manual(values=c('FALSE'=grey,'TRUE'=coral),guide='none')+scale_x_continuous(limits=c(-.83,.83),breaks=c(-.6,-.3,0,.3,.6))+labs(title='B  TF–PRII expression associations',subtitle='Mouse bulk n = 21; BH q across 12 TFs',x='Spearman ρ',y=NULL)+theme_classic(base_size=8.5)+theme(plot.title=element_text(face='bold',colour=ink,size=10),plot.subtitle=element_text(colour=muted,size=7.2),axis.text=element_text(colour=muted),axis.title.x=element_text(colour=muted,size=8),axis.ticks.y=element_blank(),panel.grid.major.x=element_line(colour='#E5EAEC',linewidth=.25),plot.margin=margin(5,10,4,5))
hub_dat <- read('ppi_hubs') %>% slice_max(degree,n=10,with_ties=FALSE) %>% mutate(gene=factor(toupper(preferred_name),levels=rev(toupper(preferred_name))))
p_c1 <- ggplot(hub_dat,aes(degree,gene))+geom_segment(aes(x=0,xend=degree,yend=gene),colour=grey,linewidth=1.05)+geom_point(size=2.6,colour=grey)+geom_text(aes(label=degree),hjust=-.25,size=2.5,colour=muted)+scale_x_continuous(limits=c(0,62),breaks=c(0,20,40,60),expand=c(0,0))+labs(title='C  STRING prior hubs',subtitle='Top degree among 743 source edges',x='Undirected degree',y=NULL)+theme_classic(base_size=8)+theme(plot.title=element_text(face='bold',colour=ink,size=9),plot.subtitle=element_text(colour=muted,size=6.5),axis.text=element_text(colour=muted),axis.title.x=element_text(colour=muted,size=7),axis.ticks.y=element_blank(),plot.margin=margin(3,7,3,3))
core_dat <- read('ppi_fig6') %>% mutate(edge=paste0(toupper(from),'—',toupper(to)),score=combined_score) %>% arrange(score) %>% slice_tail(n=12) %>% mutate(edge=factor(edge,levels=edge))
p_c2 <- ggplot(core_dat,aes(score,edge))+geom_segment(aes(x=.90,xend=score,yend=edge),colour=grey,linewidth=.9)+geom_point(size=2,colour=grey)+scale_x_continuous(limits=c(.895,1.005),breaks=c(.90,.95,1.00),labels=c('.90','.95','1.00'))+labs(title='PRII-core high-confidence edges',subtitle='12 of 37 PRII-core edges; STRING score ≥ 0.90',x='Combined score',y=NULL)+theme_classic(base_size=7.5)+theme(plot.title=element_text(face='bold',colour=ink,size=9),plot.subtitle=element_text(colour=muted,size=6.5),axis.text=element_text(colour=muted,size=6.5),axis.title.x=element_text(colour=muted,size=7),axis.ticks.y=element_blank(),plot.margin=margin(3,7,3,3))
p_c <- p_c1/p_c2+plot_annotation(title='C  STRING/PPI database-prior audit',theme=theme(plot.title=element_text(face='bold',colour=ink,size=10)))
lr_plot <- lr_fig6 %>% mutate(edge=paste0(ligand,'→',receptor,' | ',receiver),edge=factor(edge,levels=rev(edge)),receiver=factor(receiver,levels=c('epithelial_tumor','t_cell','stellate')))
p_d <- ggplot(lr_plot,aes(prevalence,edge,colour=receiver,size=mean_score))+geom_vline(xintercept=c(.5,.75),linetype='dotted',colour='#D6DEDF',linewidth=.3)+geom_point(alpha=.9)+scale_x_continuous(limits=c(.45,1),breaks=c(.5,.75,1),labels=percent_format(accuracy=1))+scale_colour_manual(values=c(epithelial_tumor=coral,t_cell=blue,stellate=green),labels=c(epithelial_tumor='epithelial/tumor',t_cell='T cell',stellate='stellate'))+scale_size_continuous(range=c(1.6,3.8),name='Mean score')+labs(title='D  Candidate ligand–receptor support',subtitle='15 receiver-specific rows; 8 unique pairs; per-row n=12–15',x='Supported-sample prevalence',y=NULL,colour='Receiver')+theme_classic(base_size=8)+theme(plot.title=element_text(face='bold',colour=ink,size=10),plot.subtitle=element_text(colour=muted,size=7),axis.text=element_text(colour=muted,size=6.3),axis.title.x=element_text(colour=muted,size=8),legend.position='bottom',legend.box='vertical',panel.grid.major.x=element_line(colour='#E5EAEC',linewidth=.25),plot.margin=margin(5,5,4,5))
e_lines <- c('Evidence labels (one value per edge):','表达关联 — observed expression/activity association with DoRothEA prior.','数据库先验 — STRING (undirected) and OmniPath-only prior edges.','候选配体–受体表达支持 — OmniPath prior plus sample-level expression.','','Integrated: 189 nodes; 253 edges (96 / 144 / 13 by evidence type).','Complete sources: TF–target 949; STRING 743; LR summary 297 rows (115 supported; 182 prior-only).','Figure 6 LR: 15 receiver-specific rows; 8 unique molecular pairs.','Eligible sample n varies by edge (12–15); samples are the unit.','Candidate evidence only; no binding, receptor activation, secretion, or causality is established.')
p_e <- ggplot()+annotate('text',x=0,y=rev(seq_along(e_lines)),label=e_lines,hjust=0,vjust=1,size=2.8,colour=ink,lineheight=1.08,family='Arial Unicode MS')+xlim(0,1)+ylim(0,length(e_lines)+1)+labs(title='E  Evidence dictionary and denominator audit')+theme_void()+theme(plot.title=element_text(face='bold',colour=ink,size=10,hjust=0,margin=margin(b=4)),plot.margin=margin(4,8,5,8))
figure <- (p_a|p_b)/(p_c|p_d)/p_e+plot_layout(heights=c(.85,2.05,1.1),widths=c(.92,1.15))+plot_annotation(title='Supplementary Figure S8. Evidence-layer audit of the PRII candidate network',subtitle='TF–target, STRING/PPI and candidate ligand–receptor edges are shown as separate hypothesis-generating evidence layers.',theme=theme(plot.title=element_text(face='bold',colour=ink,size=13,hjust=0,margin=margin(b=2)),plot.subtitle=element_text(colour=muted,size=8.2,hjust=0,margin=margin(b=6)),plot.tag=element_text(face='bold',colour=ink,size=12),plot.tag.position=c(.005,.995),plot.margin=margin(8,10,6,10)))
pdf_out <- file.path(graph_dir,'FigS8_PRII_network_evidence_audit.pdf'); tiff_out <- file.path(graph_dir,'FigS8_PRII_network_evidence_audit.tiff'); preview_out <- file.path(graph_dir,'FigS8_PRII_network_evidence_audit_preview.png')
ggsave(pdf_out,figure,width=200,height=235,units='mm',device=cairo_pdf,bg='white',limitsize=FALSE)
tiff(tiff_out,width=200,height=235,units='mm',res=600,compression='lzw',type='cairo',bg='white'); print(figure); dev.off()
ggsave(preview_out,figure,width=200,height=235,units='mm',dpi=160,bg='white',limitsize=FALSE)
run_manifest <- c('Supplementary Figure S8: evidence-layer audit of the PRII candidate network',paste0('Generated: ',format(Sys.time(),'%Y-%m-%d %H:%M:%S %Z')),'Inputs: complete TF, STRING, OmniPath prior and sample-supported LR tables; Figure 6 selected edge subsets; integrated network.','Integrated network: 189 nodes; 253 edges = 96 expression association + 144 database prior + 13 candidate ligand–receptor expression support.','Exact normalized labels: 表达关联; 数据库先验; 候选配体–受体表达支持.','TF prior: DoRothEA confidence A–C plus observed target expression and TF activity/expression association; bulk n=21; TCGA sensitivity n=149.','STRING: Mus musculus; required combined score 0.70; all edges treated as undirected database priors.','LR: OmniPath ligrecextra; summary table has 297 rows (115 with sample support, 182 prior-only); per-sample table has 4,059 rows (559 supported, 3,500 prior-only); GSE154778 has 16 samples.','Figure 6 selected LR subset: 15 receiver-specific rows and 8 unique ligand–receptor molecular pairs.','No edge establishes physical binding, TF occupancy, receptor activation, secretion, or causality.')
writeLines(run_manifest,file.path(out_dir,'S8_run_manifest.txt')); writeLines(capture.output(sessionInfo()),file.path(out_dir,'sessionInfo_S8.txt'))
message('Wrote Figure S8 and normalized source package to ',out_dir)
